# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_flect_a import L,H
RF=L+[['拉丁 reflectere；分词 reflexus，晚期也用作名词','向后弯转；折回'],['英语 reflex 的动词、名词与形容词用法','折回、反射；后来发展出神经反射等义']]
RV=L+[['拉丁 reflexus → 中世纪拉丁 reflexivus','折回的 → 指回自身的'],['英语 reflexive','反身的、自反的；反射性的']]
GN=L+[['拉丁 genu“膝”与 flectere“弯” → 晚期拉丁 genuflectere','弯膝'],['中世纪拉丁 genuflexio → 英语 genuflection','屈膝的动作；跪拜']]
FX=L+[['拉丁 flexura → 英语 flexure','弯曲、弯曲处']]
RT=L+[['近代拉丁 retroflexus，来自 retroflectere','retro“向后” + flectere“弯” → 向后弯的'],['英语 retroflex（形容词）','后弯的；卷舌的']]
FT=L+[['英语 flexible 的缩略成分与 time 组合','灵活的 + 时间'],['英语 flexitime／flextime，对应德语 Gleitzeit 的制度名称','允许在规定范围内调整上下班时间的制度']]
WD=[
E('reflex','名词、形容词 /ˈriːfleks/；少见动词 /rɪˈfleks/','反射动作；本能反应；某个较早语言形式的后继形式〔语言学〕','刺激一来，反应很快就返回去，不必先在心里讨论要不要做。','接拉丁 reflectere／reflexus“折回”。英语先有折回、光反射等用法，神经反射义后来从 reflex action 发展。',RF,'眨眼、膝跳等反应可放在 reflex 的神经生理语境里理解；fast reflexes 在日常话里也泛指反应快。语言学中的 reflex 是较早词或音在后来的语言中留下的对应形式，像历史留下的回声；它不是身体反应。','a reflex action；quick reflexes；a reflex of an earlier form。','reflex 通常不需要有意识的决定，但仍涉及神经系统；不能说“完全不经过任何神经处理”。reflection 的思考义则是认真考虑。',('The doctor checked the patient’s knee reflex.','医生检查了患者的膝跳反射。'),('Her quick reflexes helped her catch the falling cup.','她反应很快，接住了掉落的杯子。'),('The paper identifies a modern reflex of the older vowel.','论文辨认出了那个较早元音在现代语言中的后继形式。'),sources=['https://www.etymonline.com/word/reflex','https://en.wiktionary.org/wiki/reflex']),
E('reflexive','/rɪˈfleksɪv/','反身的；自反的；反射性的、下意识的','箭头发出去，又指回发出箭头的那个人或事物。','接中世纪拉丁 reflexivus；现代能看出 reflex + -ive，但历史上形容词有自己的借入路线。',RV,'She blamed herself 中，herself 指回 she，所以是 reflexive pronoun。数学里“等于”是 reflexive relation，因为每个对象都等于自己。a reflexive response 又可以指下意识的反应，不能把这里的 reflexive 误读成“仔细反思过的”。','a reflexive pronoun；a reflexive relation；a reflexive response。','reflexive 可说自动反应或指回自身；reflective 才常说沉思、反思。句法里的 myself 也可能作强调成分，须看它在句中的功能。',('“Herself” is a reflexive pronoun in this sentence.','这句话里的 herself 是反身代词。'),('Equality is a reflexive relation: every value equals itself.','相等是一种自反关系：每个值都等于它自身。'),('His first response was a reflexive refusal.','他的第一反应是下意识地拒绝。'),sources=['https://www.etymonline.com/word/reflexive','https://www.collinsdictionary.com/dictionary/english/reflexive']),
E('reflexively','/rɪˈfleksɪvli/','下意识地；反身地、自反地','还没来得及仔细想，身体或嘴巴已经先动了。','reflexive + -ly；具体义随 reflexive 的反应、语法或逻辑用法变化。',H(RV,'英语 reflexive → reflexively','反身的、反射性的 → 以这种方式'),'She reflexively apologized 常说她习惯性地先道歉，并未先判断自己是否有错。语法说明中 used reflexively 则说动词用来表达动作指回施事本人。前者关注自动反应，后者关注句子里谁指向谁。','respond reflexively；reflexively reject；use a verb reflexively。','reflexively 是下意识地；reflectively 是经过思考、若有所思地。写作时尤其容易把二者混淆。',('He reflexively reached for his phone when it vibrated.','手机一震，他便下意识地伸手去拿。'),('The verb is used reflexively in this example.','这个例句中的动词采用反身用法。'),sources=['https://en.wiktionary.org/wiki/reflexively','https://www.collinsdictionary.com/dictionary/english/reflexive']),
E('reflexivity','/ˌriːflekˈsɪvɪti/','反身性；自反性','研究别人时，也把镜头转回来看看自己怎样影响了研究。','reflexive + -ity，把“指回自身”的性质变成名词。',H(RV,'英语 reflexive → reflexivity','自反、反身的 → 自反性、反身性'),'社会研究中的 reflexivity，常要求研究者检查自己的身份、假设和提问方式怎样影响资料与解释。数学中的 reflexivity 则是关系对每个对象自身都成立，例如 x = x。共同画面是“把自己也放进考察范围”。','researcher reflexivity；reflexivity in qualitative research；the reflexivity of equality。','reflexivity 在研究中不只是记录心情，而是分析自己与研究过程的关系；reflectivity 通常谈反射性，拼写不同。',('The researcher kept a journal to support reflexivity.','研究者通过写日志来帮助审视自己对研究的影响。'),('Reflexivity requires the relation to hold for every element and itself.','自反性要求该关系对每个元素及其自身都成立。'),sources=['https://www.collinsdictionary.com/dictionary/english/reflexivity','https://en.wiktionary.org/wiki/reflexivity','https://journals.sagepub.com/doi/10.1177/1468794112468475']),
E('reflexology','英 /ˌriːflekˈsɒlədʒi/；美 /ˌriːflekˈsɑːlədʒi/','反射学；足手反射区按摩的名称','这个名字一支研究反射行为，另一支用来称呼按压手脚特定点位的做法。','reflex + -logy；早期属于欧洲反射学术语族，后来的按摩用法需要另看含义，不能仅凭名字认定其机制成立。',RF+[['20世纪欧洲 reflex 与 -logy 构成的学术词族 → 英语 reflexology','以反射解释行为的研究名称'],['后来出现的另一常用义','基于手脚特定点位与身体其他部位相对应的主张而进行的按摩']],'在心理学史中，reflexology 可指通过反射研究行为。在养生场所，它通常说足部或手部反射区按摩；“这些点直接对应特定器官并能治愈它们”属于相关主张，不能当成已经证实的事实。读这个词时，先判断是哪一种语境。','the history of reflexology；a reflexology session；foot reflexology。','reflex 的神经反射义，并不自动为 reflexology 按摩的各种疗效主张提供证明。相同词根不能代替证据。',('The chapter discusses reflexology in the history of psychology.','这一章讨论心理学史中的反射学。'),('The brochure lists reflexology among the available massage services.','宣传册把反射区按摩列在可提供的按摩服务中。'),sources=['https://www.etymonline.com/word/reflexology','https://www.merriam-webster.com/dictionary/reflexology','https://www.nccih.nih.gov/health/reflexology']),
E('genuflect','/ˈdʒenjuflekt/','屈膝跪拜；卑躬屈膝、过分服从〔比喻〕','膝盖弯下去，身体降低，表示敬意；比喻时则是姿态也低到不敢坚持自己。','genu- 接拉丁 genu“膝”，flect 接“弯”。英语动词常分析为从较早的 genuflection 逆构，不能把英语历史顺序画反。',H(GN,'英语 genuflection → genuflect〔逆构〕','跪拜这一行为 → 跪拜'),'在宗教礼仪中 genuflect 可以是屈一膝致敬；在评论中 genuflect to power 是讽刺对权势低头。字面动作不天然含贬义，贬义常来自把它用于人的服从态度。','genuflect before an altar；genuflect to authority。','kneel 只是跪下这一姿势；genuflect 常带有致敬或礼仪意味，比喻时也可能说谄媚。',('Some worshippers genuflect before the altar.','一些礼拜者在祭坛前屈膝致敬。'),('The writer refuses to genuflect to fashion.','这位作家不愿对流行风尚俯首听命。'),sources=['https://www.etymonline.com/word/genuflect','https://www.merriam-webster.com/dictionary/genuflect']),
E('genuflection','/ˌdʒenjuˈflekʃən/','屈膝礼；跪拜；过分恭顺〔比喻〕','把弯膝致敬这个动作当作一件完整的礼仪或姿态来讲。','中世纪拉丁 genuflexio 接晚期拉丁 genuflectere，背后是 genu“膝” + flectere“弯”。英语名词早于动词 genuflect。',GN,'a genuflection 可以指一次屈膝礼；political genuflection 常是带讽刺的比喻，形容对有权势者表示顺从。现代看上去像 genuflect 加 -ion，但真实的英语借入顺序恰好不能这样推。','make a genuflection；a gesture of genuflection；genuflection to power。','genuflection 是动作或态度的名词；genuflect 是做这个动作的动词。词尾更长，不代表它一定出现得更晚。',('He made a brief genuflection before taking his seat.','落座前，他简短地行了一个屈膝礼。'),('The critic saw the speech as an act of genuflection to power.','评论者认为那番讲话是在向权势卑躬屈膝。'),sources=['https://www.etymonline.com/word/genuflection','https://www.merriam-webster.com/dictionary/genuflection']),
E('flexure','英 /ˈflekʃə/；美 /ˈflekʃər/','弯曲；弯曲处；挠曲','一条原本直的东西弯出了弧，也可能把那段弯的位置单独指出来。','来自拉丁 flexura“弯曲、弯处”，以 flexus 的词干接 -ura 形成名词。',FX,'工程里的 flexure 可以说梁、薄片等弯曲变形；解剖中的 a flexure 则常说器官的转弯处。它既能指“弯这件事”，也能指“那个弯”，不是只指关节活动。','flexure of a beam；a flexure in a structure；a bend or flexure。','flexion 常用于关节屈曲；flexure 还常用于结构弯曲和具体弯曲部位。',('The experiment measured the flexure of a thin metal strip.','实验测量了一根薄金属条的弯曲情况。'),('The diagram marks a flexure in the intestine.','图中标出了一处肠道弯曲部位。'),sources=['https://www.merriam-webster.com/dictionary/flexure']),
E('flexural','/ˈflekʃərəl/','弯曲的；与抗弯、挠曲有关的','把材料放到“承受弯曲”这种情境里，看它怎样表现。','flexure + -al，形成形容词。',H(FX,'英语 flexure → flexural','弯曲 → 与弯曲有关的'),'flexural strength 说材料在规定弯曲试验中承受弯曲应力的能力；flexural stiffness 说抵抗弯曲变形的程度。两者都与弯有关，却不等于同一个指标：不容易弯和不容易弯断要分开。','flexural strength；flexural stiffness；a flexural test。','flexural 表示“关于弯曲”；flexible 表示“容易或能够弯曲”。一个 flexural test 完全可以测试很硬的材料。',('The engineers compared the materials’ flexural stiffness.','工程师比较了这些材料的抗弯刚度。'),('The sample failed during the flexural test.','试样在弯曲试验中失效了。'),sources=['https://www.merriam-webster.com/dictionary/flexural','https://en.wiktionary.org/wiki/flexural','https://www.instron.com/en/resources/test-types/flexural-testing/']),
E('flexitime','/ˈfleksitaɪm/','弹性工作时间制〔主要英式〕','一天仍要完成约定工时，但钟表上的起点、终点可以在规定范围内移动。','flexi- 是 flexible 的缩略成分，与 time 组合；现代制度名称对应德语 Gleitzeit“滑动时间”的概念。',FT,'flexitime 通常允许员工调整开始和结束工作的时间，可能仍有必须共同在岗的核心时段。它不自动等于减少工时，也不自动等于在家办公：调整的是时间安排。','work flexitime；a flexitime scheme；offer flexitime。','flexitime 是时间弹性；remote work 是工作地点安排。这两者可以结合，也可以分开。',('The company introduced flexitime for office staff.','公司为办公室员工推行了弹性工作时间制。'),('Flexitime allows her to start earlier on some days.','弹性工时让她能在某些日子提前开始工作。'),sources=['https://dictionary.cambridge.org/dictionary/english/flexitime','https://www.etymonline.com/word/flextime']),
E('flextime','/ˈflekstaɪm/','弹性工作时间制〔主要美式〕','总工时有要求，上下班的钟点却留了一点可调空间。','flex + time；与 flexitime 是同一现代制度名称的常见形式，不能把少一个 i 当成另一种制度。',H(FT,'美式常用形式 flextime','弹性工作时间制'),'a flextime policy 规定员工可以怎样调整工作起止时间。制度可能设核心时段、打卡和工时累计规则，具体要看公司安排。这个词本身只表达“时间可灵活调整”，并不承诺想来就来。','a flextime policy；a flextime schedule；offer flextime。','flextime 与 flexitime 主要是地区用词差别；part time 则说工作时数少于通常的全职安排。',('Flextime helps him avoid the busiest commute.','弹性工时帮助他避开最拥堵的通勤时段。'),('The handbook explains the new flextime policy.','员工手册解释了新的弹性工时政策。'),sources=['https://dictionary.cambridge.org/us/dictionary/english/flextime','https://www.etymonline.com/word/flextime']),
E('retroflex','英 /ˈretrəʊfleks/；美 /ˈretroʊfleks/','向后弯的；卷舌的；向后弯曲〔动词〕','尖端没有继续向前，而是往后回卷。','retro-“向后” + flex-，形容词接近代拉丁 retroflexus。英语动词较晚，可由 retroflexed 逆构，不必假定先有动词才有形容词。',RT,'语音学里的 retroflex 常译卷舌，典型画面是舌尖抬起并向后转；实际发音可有差异，不一定都夸张地卷成钩。植物学等场景则可以说某个部分向后弯。这里的 retro- 是方向，不是“复古风格”。','a retroflex consonant；a retroflex sound；retroflex articulation。','retroflex 描述特定后弯或语音部位；reflect 是反射，词形接近却不能互换。',('The lesson contrasts dental and retroflex consonants.','这一课对比齿音和卷舌辅音。'),('The illustration shows a retroflex tip on the leaf.','插图展示了叶片向后弯的尖端。'),sources=['https://www.etymonline.com/word/retroflex','https://www.collinsdictionary.com/dictionary/english/retroflex']),
E('retroflexion','英 /ˌretrəʊˈflekʃən/；美 /ˌretroʊˈflekʃən/','后屈、向后弯；卷舌发音','把“尖端或器官向后折”的状态单独拿出来描述。','接新拉丁 retroflexio，来自 retroflexus“后弯的”的名词支线；英语名词不应直接画成较晚动词 retroflex 的后代。',L+[['近代拉丁 retroflexus → retroflexio','向后弯的 → 向后弯曲'],['英语 retroflexion','后屈；卷舌发音或其语音特征']],'语音学中 retroflexion 可说舌尖向后抬转的发音动作及相关音色；解剖描述中则说某个结构后屈。这个词本身是形态或动作描述，是否异常还要看具体结构和语境。','tongue retroflexion；retroflexion in speech；a degree of retroflexion。','retroflex 是形容词或动词；retroflexion 是名词。向后弯的部位不一定要先经过英语动词命名，才能有名词名称。',('The study compares degrees of tongue retroflexion.','研究比较了舌部后卷的不同程度。'),('The diagram shows the organ’s retroflexion.','图中展示了该器官的后屈状态。'),sources=['https://www.collinsdictionary.com/dictionary/english/retroflexion','https://www.etymonline.com/word/retroflex']),
]
